//! The orthogonal polynomials and Legendre functions against mpmath (ground
//! truth) and SciPy (parity), for `f64` and `xprec::Df64`, plus SciPy's
//! non-finite and zero results.
//!
//! Reference data: `tests/data`, generated by `scripts/gen_specials_reference.py`
//! (`orthogonal`). The last argument of an integer-degree row is its *scale*,
//! the largest `|p_j|` of the recurrence for `j <= n`. A polynomial value near
//! a zero has an absolute rather than a relative error of about `C (n + 1) eps
//! scale`, so each assertion has a relative tolerance and that absolute floor;
//! the constants `C` below are 3x or more above the worst measured error.
//!
//! The `f64` rows run in every configuration; the `Df64` tests need the `xprec`
//! feature (on by default).

#[path = "../src/refdata.rs"]
mod refdata;

use refdata::{orthogonal_special_values, rows, same, Row};
use specials::{LegendreType, Real};
#[cfg(feature = "xprec")]
use xprec::Df64;

