/// `legendre_p` is the same polynomial as `eval_legendre_int` for `n >= 0` (xsf has a second
/// recurrence for it), and NaN for `n < 0`.
#[test]
fn legendre_p_matches_the_legendre_polynomial_rows() {
    let all = rows("eval_legendre_int");
    for r in all.iter().filter(|r| r.is_f64() && r.args[0].0 >= 0.0) {
        let n = r.args[0].0 as i32;
        let x: f64 = r.args_as::<f64>()[1];
        let got = specials::legendre_p(n, x);
        let e = error(got, r.reference, floor_of(r, 100.0, f64::EPSILON, 1e-11));
        assert!(
            e <= 1e-11,
            "legendre_p({n}, {x}): {got:e} vs {:?}, err {e:e}",
            r.reference
        );
    }
    #[cfg(feature = "xprec")]
    for r in all.iter().filter(|r| r.args[0].0 >= 0.0) {
        let n = r.args[0].0 as i32;
        let x: Df64 = r.args_as::<Df64>()[1];
        let got = specials::legendre_p(n, x);
        let e = error(
            got,
            r.reference,
            floor_of(r, 100.0, 2.0_f64.powi(-105), 2e-29),
        );
        assert!(
            e <= 2e-29,
            "legendre_p({n}, {x:?}): {got:?} vs {:?}, err {e:e}",
            r.reference
        );
    }
    assert!(specials::legendre_p(-1, 0.3_f64).is_nan());
}

/// The second-kind functions at `x = +-1`: `Q_k(1) = +inf`, `Q_k(-1) = (-1)^(k+1) inf`,
/// `Q_k^i(1) = (-1)^i inf`, `Q_k^i(-1) = (-1)^(k+1) inf` (DLMF 14.9 parity of `Q_n^m`,
/// the sign of `d^m ln(1 - x)`), and NaN derivatives, which tend to opposite infinities from
/// the two sides. xsf stores `1e300` in every entry.
fn second_kind_endpoints<T: Real>() {
    let (inf, nan) = (T::infinity(), T::nan());
    let one = T::one();
    let (q, d) = specials::lqn(3, one);
    assert_eq!(q, vec![inf; 4]);
    assert!(d.iter().all(|v| v.is_nan()));
    let (q, d) = specials::lqn(3, -one);
    assert_eq!(q, vec![-inf, inf, -inf, inf]);
    assert!(d.iter().all(|v| v.is_nan()));
    let (q, d) = specials::lqmn(2, 2, one);
    assert_eq!(q, vec![inf, inf, inf, -inf, -inf, -inf, inf, inf, inf]);
    assert!(d.iter().all(|v| v.is_nan()));
    let (q, d) = specials::lqmn(2, 2, -one);
    assert_eq!(q, vec![-inf, inf, -inf, -inf, inf, -inf, -inf, inf, -inf]);
    assert!(d.iter().all(|v| v.is_nan()));
    let _ = nan;
}

#[test]
fn second_kind_at_the_endpoints() {
    second_kind_endpoints::<f64>();
    #[cfg(feature = "xprec")]
    second_kind_endpoints::<Df64>();
}

/// Documented behavior of the `f64` kernels where they are not accurate: a
/// reproducer for each entry of `docs/upstream-issues.md`, next to the correct `Df64`
/// value where the double-double recurrence has one.
#[test]
fn f64_limits_are_the_documented_ones() {
    // eval_jacobi: the recurrence divides by alpha + 1.
    assert!(specials::eval_jacobi_int(2, -1.0_f64, 0.5, -0.75).is_nan());
    assert_eq!(
        specials::eval_jacobi_int(2, -1.0 + 2.0_f64.powi(-52), 0.5_f64, -0.75),
        0.0
    );
    // eval_jacobi and eval_genlaguerre: the normalization binom(n + alpha, n) overflows.
    assert_eq!(
        specials::eval_genlaguerre_int(1000, 1000.0_f64, 1000.0),
        f64::INFINITY
    );
    assert!(specials::eval_jacobi_int(1000, 1000.0_f64, 0.0, -1.0).is_nan());
    // pmv: 1 + r cancels next to the zero of an odd polynomial.
    assert_eq!(specials::pmv(0.0_f64, 1.0, 1e-15), 1.1102230246251565e-15);
    assert!(specials::pmv(0.0_f64, 1.0, 1e-30) == 0.0);
    // pmv of a non-integer degree is not accurate to 3e-13 everywhere: next to a zero its relative
    // error reaches 9e-12 (mpmath: -3.133242096893011581e-14), in f64 and in Df64 alike.
    let want = -3.133242096893012e-14;
    let v = specials::pmv(-6.0_f64, 39.5642498749246, -0.43842672603356236);
    assert!(
        ((v - want) / want).abs() > 1e-12 && ((v - want) / want).abs() < 2e-11,
        "{v:e}"
    );
    #[cfg(feature = "xprec")]
    {
        let d = Df64::from;
        let v = specials::pmv(d(-6.0), d(39.5642498749246), d(-0.43842672603356236)).hi();
        assert!(
            ((v - want) / want).abs() > 1e-12 && ((v - want) / want).abs() < 2e-11,
            "{v:e}"
        );
    }
    // lqn and lqmn: xsf stores 1e300 at x = +-1; this crate returns the infinities
    // (checked in `second_kind_at_the_endpoints`).
    // The negative degree has no meaning: NaN rather than xsf's z or 0.
    assert!(specials::assoc_legendre_p(-1, 0, 0.3_f64, LegendreType::Ferrers).is_nan());
    #[cfg(feature = "xprec")]
    {
        let d = |x: f64| Df64::from(x);
        let tiny = Df64::from(-1.0 + 2.0_f64.powi(-52));
        // P_2^(a, 1/2)(x) at a = -1 + 2^-52 and at -1, from the relation P_n^(-1,b) = (n + b) / (2n) (x - 1) P_(n-1)^(1,b)
        let want = 1.162109375;
        assert!(
            (specials::eval_jacobi_int(2, tiny, d(0.5), d(-0.75)) - d(want))
                .abs()
                .hi()
                < 1e-15
        );
        assert!(
            (specials::eval_jacobi_int(2, d(-1.0), d(0.5), d(-0.75)) - d(want))
                .abs()
                .hi()
                < 1e-15
        );
        assert!(
            (specials::eval_jacobi_int(1000, d(1000.0), d(0.0), d(-1.0)) - d(1.0))
                .abs()
                .hi()
                < 1e-27
        );
        let (a, b) = (specials::pmv(d(0.0), d(1.0), d(1e-15)), d(1e-15));
        assert!(((a - b) / b).abs().hi() < 1e-30);
    }
}

/// The true result is beyond the range of `f64`: `Df64` returns the infinity with the sign of
/// the polynomial; xsf's `f64` kernels return NaN when the Hermite or Laguerre recurrence
/// overflows (`docs/upstream-issues.md`). Values from mpmath: `H_660(-14.568...) = 5.1e932`,
/// `H_661 = -2.7e933`, `H_284(-16.467...) = 2.7e388`, `He_995(48.98...) = -1.1e1536`,
/// `L_2000(1e5) = 5.6e4246`, `L_2001(1e5) = -2.7e4248`.
#[test]
fn overflow_is_a_signed_infinity_in_df64_and_xsfs_nan_in_f64() {
    let cases: [(&str, i64, f64, f64); 7] = [
        ("eval_hermite", 660, -14.568126673025812, f64::INFINITY),
        ("eval_hermite", 661, -14.568126673025812, f64::NEG_INFINITY),
        ("eval_hermite", 284, -16.46689288168518, f64::INFINITY),
        (
            "eval_hermitenorm",
            995,
            48.980587028696874,
            f64::NEG_INFINITY,
        ),
        ("eval_laguerre_int", 2000, 1e5, f64::INFINITY),
        ("eval_laguerre_int", 2001, 1e5, f64::NEG_INFINITY),
        ("eval_hermite", 3, 1e300, f64::INFINITY),
    ];
    for (name, n, x, want) in cases {
        let f = eval::<f64>(name, &[n as f64, x]);
        // xsf's NaN, except where the intermediate products still overflow to the right infinity
        assert!(f.is_nan() || f == want, "f64 {name}({n}, {x}) = {f}");
        #[cfg(feature = "xprec")]
        {
            let d = eval::<Df64>(name, &[Df64::from(n as f64), Df64::from(x)]).hi();
            assert_eq!(d, want, "Df64 {name}({n}, {x})");
        }
    }
    // the same polynomial of the kinds where xsf returns the infinity correctly
    #[cfg(feature = "xprec")]
    {
        let d = Df64::from;
        assert_eq!(
            specials::eval_chebyt_int(3, d(-1e300)).hi(),
            f64::NEG_INFINITY
        );
        assert_eq!(specials::eval_chebyt_int(4, d(-1e300)).hi(), f64::INFINITY);
        assert_eq!(
            specials::eval_legendre_int(3, d(-1e300)).hi(),
            f64::NEG_INFINITY
        );
        assert_eq!(
            specials::eval_chebyu_int(-5, d(1e300)).hi(),
            f64::NEG_INFINITY
        );
        assert_eq!(specials::eval_hermitenorm(2, d(-1e300)).hi(), f64::INFINITY);
        // a documented NaN of finite arguments stays NaN
        assert!(specials::eval_jacobi_int(3, d(-1.5), d(-0.5), d(0.3))
            .hi()
            .is_nan());
        assert!(specials::eval_genlaguerre_int(2, d(-2.0), d(0.3))
            .hi()
            .is_nan());
        assert!(specials::eval_hermite(-1, d(0.3)).hi().is_nan());
    }
}

/// `Df64` evaluates `Q_n` by Miller's backward recurrence for `n acosh abs(x) > 2`, whose
/// start index is `n + 40 / acosh abs(x)`: the work stays linear in `n` and the result
/// satisfies the three-term recurrence and decays like `exp(-n acosh x)`.
#[cfg(feature = "xprec")]
#[test]
fn df64_second_kind_backward_recurrence_is_consistent() {
    for (n, x) in [
        (2000_usize, 1.0001),
        (2000, 1.5),
        (500, 1.0000001),
        (100, 1e6),
    ] {
        let xd = Df64::from(x);
        let (q, qd) = specials::lqn(n, xd);
        assert_eq!(q.len(), n + 1);
        // Below 1e-280 the low word of a double-double is subnormal.
        for j in (1..n).filter(|&j| q[j + 1].hi() > 1e-280) {
            let jf = Df64::from(j as f64);
            let lhs = (jf + Df64::from(1.0)) * q[j + 1];
            let t1 = (Df64::from(2.0) * jf + Df64::from(1.0)) * xd * q[j];
            let t2 = jf * q[j - 1];
            // relative to the terms: the difference cancels for large x
            assert!(
                ((lhs - (t1 - t2)).abs() / (t1.abs() + t2.abs())).hi() < 1e-28,
                "n = {n}, x = {x}, j = {j}"
            );
        }
        // Q_n decreases and is positive for x > 1, and its derivative is negative.
        assert!(
            q.windows(2)
                .all(|w| w[0].hi() >= w[1].hi() && w[1].hi() >= 0.0),
            "n = {n}, x = {x}"
        );
        assert!(qd.iter().all(|d| d.hi() <= 0.0), "n = {n}, x = {x}");
        // Q_0 = ln((x + 1)/(x - 1)) / 2 is the normalization.
        if x < 10.0 {
            let q0 = (((xd + Df64::from(1.0)) / (xd - Df64::from(1.0))).ln()) / Df64::from(2.0);
            assert!(((q[0] - q0) / q0).abs().hi() < 1e-27, "n = {n}, x = {x}");
        }
    }
}

/// The names that the tests above exercise are all the rows of the family.
#[test]
fn every_row_file_is_tested() {
    let tested: Vec<&str> = INT_NAMES
        .iter()
        .chain(REAL_NAMES.iter())
        .chain(LEGENDRE_NAMES.iter())
        .copied()
        .collect();
    assert_eq!(tested.len(), 15 + 13 + 6);
    for t in INT_TOL.iter().map(|t| t.0) {
        assert!(INT_NAMES.contains(&t));
    }
    for t in REAL_TOL.iter().map(|t| t.0) {
        assert!(REAL_NAMES.contains(&t));
    }
    for t in LEGENDRE_TOL.iter().map(|t| t.0) {
        assert!(LEGENDRE_NAMES.contains(&t));
    }
}
